package com.example.marketplace.claim.infrastructure;
import com.example.marketplace.claim.api.ExchangePhysical;
import com.example.marketplace.claim.api.Exchanges;
import com.example.marketplace.order.api.OrderQueries;
import com.example.marketplace.order.api.OrderRejected;
import com.example.marketplace.order.api.ExchangeApplications;
import com.example.marketplace.order.api.PhysicalOrders;
import com.example.marketplace.inventory.api.PhysicalStocks;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.sql.Timestamp;
import org.springframework.context.annotation.Profile;
import org.springframework.stereotype.Service;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.jdbc.core.namedparam.MapSqlParameterSource;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
@Service @Profile("db")
public final class JdbcExchangePhysical implements ExchangePhysical {
 private final NamedParameterJdbcTemplate jdbc;private final JdbcExchanges exchanges;private final ExchangeApplications applications;private final PhysicalOrders physical;private final PhysicalStocks stocks;private final TransactionTemplate tx;private final tools.jackson.databind.ObjectMapper mapper=new tools.jackson.databind.ObjectMapper();
 public JdbcExchangePhysical(NamedParameterJdbcTemplate jdbc,JdbcExchanges exchanges,ExchangeApplications applications,PhysicalOrders physical,PhysicalStocks stocks,PlatformTransactionManager manager) { this.jdbc=jdbc;this.exchanges=exchanges;this.applications=applications;this.physical=physical;this.stocks=stocks;this.tx=new TransactionTemplate(manager); }
 @Override public Exchanges.Progress receive(UUID id,OrderQueries.Authority authority,CollectionCommand input) {
  if(input==null) { throw new OrderRejected(400); }validate(input.key(),input.expectedRevision(),input.reason());if(input.units()==null||input.units().isEmpty()||input.units().size()>1980||input.units().stream().anyMatch(u->u==null||u.itemId()==null||u.ordinal()<0||u.ordinal()>98||u.status()==null)||input.units().stream().map(u->u.itemId()+":"+u.ordinal()).distinct().count()!=input.units().size()) { throw new OrderRejected(400); }
  var units=input.units().stream().sorted(java.util.Comparator.comparing((Received u)->u.itemId().toString()).thenComparingInt(Received::ordinal)).toList();String reason=input.reason().strip(),fingerprint=hash("RECEIVE|"+input.expectedRevision()+"|"+units+"|"+reason);
  return tx.execute(t->{var source=applications.lockSeller(authority,id);var fixed=physical.application(id);var row=exchanges.lock(id);var prior=prior(id,input.key(),fingerprint);if(prior!=null) { applications.lockSeller(authority,id);return prior; }check(row,input.expectedRevision());long version=((Number)row.get("version")).longValue()+1;var at=jdbc.queryForObject("SELECT clock_timestamp()",Map.of(),Timestamp.class).toInstant();String actor=actor(authority);
   for(var u:units) { var selected=fixed.stream().filter(s->s.itemId().equals(u.itemId())&&s.ordinal()==u.ordinal()).findFirst().orElseThrow(()->new OrderRejected(409));var p=new MapSqlParameterSource("id",id).addValue("item",u.itemId()).addValue("ordinal",u.ordinal());if(jdbc.queryForObject("SELECT count(*) FROM marketplace.claim_exchange_inspection_unit WHERE exchange_id=:id AND item_id=:item AND ordinal=:ordinal",p,Integer.class)!=0) { throw new OrderRejected(409); }var old=jdbc.queryForList("SELECT status FROM marketplace.claim_exchange_collection WHERE exchange_id=:id AND item_id=:item AND ordinal=:ordinal ORDER BY version DESC LIMIT 1",p,String.class);if(!old.isEmpty()&&(old.getFirst().equals("RECEIVED")||old.getFirst().equals(u.status().name()))) { throw new OrderRejected(409); }
    jdbc.update("INSERT INTO marketplace.claim_exchange_collection(id,exchange_id,item_id,ordinal,physical_id,status,version,actor,reason,occurred_at) VALUES(:event,:id,:item,:ordinal,:physical,:status,:version,:actor,:reason,:at)",p.addValue("event",UUID.randomUUID()).addValue("physical",selected.id()).addValue("status",u.status().name()).addValue("version",version).addValue("actor",actor).addValue("reason",reason).addValue("at",Timestamp.from(at)));
   }
   String state=state(id,row.get("approved_at")!=null);var result=finish(id,input.key(),fingerprint,state,version,reason,authority,at);applications.lockSeller(authority,id);if(!source.orderId().equals(exchanges.source(id).orderId())) { throw new OrderRejected(409); }return result;
  });
 }
 @Override public Exchanges.Progress inspect(UUID id,OrderQueries.Authority authority,InspectionCommand input) {
  if(input==null) { throw new OrderRejected(400); }validate(input.key(),input.expectedRevision(),input.reason());if(input.units()==null||input.units().isEmpty()||input.units().size()>1980||input.units().stream().anyMatch(u->u==null||u.itemId()==null||u.ordinal()<0||u.ordinal()>98||u.condition()==null||u.responsibility()==null)||input.units().stream().map(u->u.itemId()+":"+u.ordinal()).distinct().count()!=input.units().size()) { throw new OrderRejected(400); }
  var units=input.units().stream().sorted(java.util.Comparator.comparing((Inspected u)->u.itemId().toString()).thenComparingInt(Inspected::ordinal)).toList();String reason=input.reason().strip(),fingerprint=hash("INSPECT|"+input.expectedRevision()+"|"+units+"|"+reason);
  return tx.execute(t->{applications.lockSeller(authority,id);var fixed=physical.application(id);var row=exchanges.lock(id);var prior=prior(id,input.key(),fingerprint);if(prior!=null) { applications.lockSeller(authority,id);return prior; }check(row,input.expectedRevision());long version=((Number)row.get("version")).longValue()+1;UUID inspection=UUID.randomUUID();var at=jdbc.queryForObject("SELECT clock_timestamp()",Map.of(),Timestamp.class).toInstant();var p=new MapSqlParameterSource("inspection",inspection).addValue("id",id).addValue("version",version).addValue("actor",actor(authority)).addValue("reason",reason).addValue("at",Timestamp.from(at));
   jdbc.update("INSERT INTO marketplace.claim_exchange_inspection(id,exchange_id,version,actor,reason,occurred_at) VALUES(:inspection,:id,:version,:actor,:reason,:at)",p);var inbound=new java.util.ArrayList<PhysicalStocks.Unit>();
   for(var u:units) { var selected=fixed.stream().filter(s->s.itemId().equals(u.itemId())&&s.ordinal()==u.ordinal()).findFirst().orElseThrow(()->new OrderRejected(409));p.addValue("item",u.itemId()).addValue("ordinal",u.ordinal());var received=jdbc.queryForList("SELECT id,status FROM marketplace.claim_exchange_collection WHERE exchange_id=:id AND item_id=:item AND ordinal=:ordinal ORDER BY version DESC LIMIT 1",p);if(received.size()!=1||!received.getFirst().get("status").equals("RECEIVED")||jdbc.queryForObject("SELECT count(*) FROM marketplace.claim_exchange_inspection_unit WHERE exchange_id=:id AND item_id=:item AND ordinal=:ordinal",p,Integer.class)!=0) { throw new OrderRejected(409); }
    jdbc.update("INSERT INTO marketplace.claim_exchange_inspection_unit(inspection_id,exchange_id,item_id,ordinal,physical_id,collection_id,condition,responsibility,restitution_id) VALUES(:inspection,:id,:item,:ordinal,:physical,:collection,:condition,:responsibility,:restitution)",p.addValue("physical",selected.id()).addValue("collection",received.getFirst().get("id")).addValue("condition",u.condition().name()).addValue("responsibility",u.responsibility().name()).addValue("restitution",u.condition()==Condition.SALEABLE?inspection:null));
    if(u.condition()==Condition.SALEABLE) { inbound.add(new PhysicalStocks.Unit(selected.id(),selected.stock().id())); }
   }
   if(!inbound.isEmpty()) { stocks.restore(new PhysicalStocks.Inbound(inspection,id,fixed.getFirst().stock().checkoutId(),PhysicalStocks.Purpose.EXCHANGE,inbound)); }
   String state=state(id,row.get("approved_at")!=null);var result=finish(id,input.key(),fingerprint,state,version,reason,authority,at);applications.lockSeller(authority,id);return result;
  });
 }
 private String state(UUID id,boolean approved) { int total=jdbc.queryForObject("SELECT count(*) FROM marketplace.claim_exchange_unit WHERE exchange_id=:id",Map.of("id",id),Integer.class);var facts=jdbc.queryForMap("SELECT count(*) FILTER(WHERE c.status='LOST_REPORTED') lost,count(*) FILTER(WHERE c.status='RECEIVED' AND i.inspection_id IS NOT NULL) ready FROM marketplace.claim_exchange_unit u LEFT JOIN LATERAL(SELECT status FROM marketplace.claim_exchange_collection c WHERE c.exchange_id=u.exchange_id AND c.item_id=u.item_id AND c.ordinal=u.ordinal ORDER BY version DESC LIMIT 1)c ON true LEFT JOIN marketplace.claim_exchange_inspection_unit i ON i.exchange_id=u.exchange_id AND i.item_id=u.item_id AND i.ordinal=u.ordinal WHERE u.exchange_id=:id",Map.of("id",id));return ((Number)facts.get("lost")).intValue()>0?"REVIEW_REQUIRED":approved&&((Number)facts.get("ready")).intValue()==total?"READY":"COLLECTING"; }
 private Exchanges.Progress prior(UUID id,String key,String fingerprint) { var rows=jdbc.queryForList("SELECT fingerprint,receipt::text FROM marketplace.claim_exchange_command WHERE exchange_id=:id AND command_key=:key",Map.of("id",id,"key",key));if(rows.isEmpty()) { return null; }if(!fingerprint.equals(rows.getFirst().get("fingerprint"))) { throw new OrderRejected(409); }return mapper.readValue(rows.getFirst().get("receipt").toString(),Exchanges.Progress.class); }
 private Exchanges.Progress finish(UUID id,String key,String fingerprint,String state,long version,String reason,OrderQueries.Authority authority,java.time.Instant at) { jdbc.update("UPDATE marketplace.claim_exchange_request SET state=:state,version=:version WHERE id=:id",Map.of("state",state,"version",version,"id",id));exchanges.history(id,state,version,reason,authority,at);exchanges.event(id,"physical-"+version,at);var result=exchanges.progress(id);jdbc.update("INSERT INTO marketplace.claim_exchange_command(exchange_id,command_key,fingerprint,action,version,receipt) VALUES(:id,:key,:hash,:state,:version,CAST(:receipt AS jsonb))",Map.of("id",id,"key",key,"hash",fingerprint,"state",state,"version",version,"receipt",mapper.writeValueAsString(result)));return result; }
 private static void check(Map<String,Object> row,long expected) { if(((Number)row.get("version")).longValue()!=expected||!List.of("REQUESTED","RESPONSIBILITY_PENDING","APPROVED","COLLECTING","REVIEW_REQUIRED").contains(row.get("state").toString())) { throw new OrderRejected(409); } }
 private static String actor(OrderQueries.Authority authority) { return authority.member()==null?"GAS":"MEMBER:"+authority.member(); }
 private static void validate(String key,Long revision,String reason) { if(key==null||!key.matches("[A-Za-z0-9][A-Za-z0-9._:-]{0,99}")||revision==null||revision<0||reason==null||reason.isBlank()||reason.length()>500) { throw new OrderRejected(400); } }
 private static String hash(String text) { try { return java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(text.getBytes(java.nio.charset.StandardCharsets.UTF_8))); }catch(java.security.NoSuchAlgorithmException impossible) { throw new IllegalStateException(impossible); } }
}
